def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    ink = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]
    # Complete interrupted horizontal bars (3+ markers) and vertical strokes
    # (4+ markers), changing only non-ink cells between their outer markers.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == ink]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] != ink:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == ink]
        if len(rows) >= 4:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] != ink:
                    out[r][c] = 2
    return out
